Detection follows a tiered strategy, from most to least authoritative:

1. Explicit override via the ``DATAHUB_CALLER`` environment variable.
2. Known env var signatures present in the current process environment.
3. Signatures found in the *parent* process environment (Linux ``/proc``,
   macOS ``ps eww``), matched against :data:`_CALLER_SIGNATURES`.
4. Heuristics based on the ancestor process-name chain.

The public entrypoint :func:`identify_caller` never raises and always returns
a short, single-line label string.
"""

import functools
import logging
import os
import platform
import subprocess
from typing import Dict, List, Optional

logger = logging.getLogger(__name__)

# Timeout (in seconds) for the small ``ps`` subprocesses used for process-tree
# introspection. Kept short so detection can never noticeably slow down the CLI.
_SUBPROCESS_TIMEOUT = 1.0

# Maximum length of the returned label. The value is embedded in HTTP headers,
# so we keep it well bounded.
_MAX_CALLER_LENGTH = 200

# Ordering is significant: AI coding tools are listed before CI systems so that
# when a parent environment contains multiple matching signatures, the more
# specific tool wins. Keys without "=" are matched by key-presence (``KEY=``);
# keys containing "=" are matched as an exact ``KEY=value`` substring.
_CALLER_SIGNATURES: Dict[str, str] = {
    # AI coding tools.
    "CLAUDECODE": "claude-code",
    "CURSOR_TRACE_ID": "cursor",
    "LANGCHAIN_TRACING_V2": "langchain",
    "LANGSMITH_API_KEY": "langchain",
    "LANGGRAPH_API_URL": "langgraph",
    # CI systems.
    "GITHUB_ACTIONS": "github-actions",
    "JENKINS_URL": "jenkins",
}

# Interactive shells used to distinguish a plain terminal invocation from a
# tool-driven one in the process-tree heuristic tier.
_SHELL_NAMES = {"bash", "zsh", "fish", "sh", "dash", "tcsh", "ksh"}


def _is_truthy(value: Optional[str]) -> bool:
    """Return True if an env var value should be treated as an enabled flag."""
    if value is None:
        return False
    return value.strip().lower() not in ("", "0", "false", "no")


def _match_signatures(env_text: str) -> Optional[str]:
    """Return the label of the first matching signature in ``env_text``.

    ``env_text`` is a space- or newline-separated dump of ``KEY=value`` pairs.
    For signatures without "=", we check for the presence of ``KEY=``. For
    signatures containing "=", we look for the exact ``KEY=value`` substring.
    """
    for key, label in _CALLER_SIGNATURES.items():
        if "=" in key:
            if key in env_text:
                return label
        elif f"{key}=" in env_text:
            return label
    return None


def _read_parent_env_linux(ppid: int) -> Optional[str]:
    """Read the environment of ``ppid`` from ``/proc/<ppid>/environ`` on Linux.

    Null-byte separators are converted to newlines. Returns None if the file
    cannot be read (permissions or the process no longer exists).
    """
    try:
        with open(f"/proc/{ppid}/environ", "rb") as f:
            data = f.read()
    except (PermissionError, FileNotFoundError):
        return None
    return data.decode("utf-8", errors="replace").replace("\0", "\n")


def _read_parent_env_macos(ppid: int) -> Optional[str]:
    """Read the environment of ``ppid`` via ``ps eww`` on macOS."""
    try:
        result = subprocess.run(
            ["ps", "eww", "-p", str(ppid), "-o", "command="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout


def _get_full_command(pid: int) -> Optional[str]:
    """Return the full command line for ``pid`` (stripped), or None on failure."""
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "args="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    return result.stdout.strip()


def _get_process_name(pid: int) -> Optional[str]:
    """Return the basename of the command for ``pid`` (e.g. '/usr/bin/zsh' -> 'zsh').

    A ``java`` process running a Gradle daemon is reported as ``gradle`` so the
    heuristic tier can distinguish it from other JVM invocations.
    """
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "comm="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None

    name = os.path.basename(result.stdout.strip())
    if name == "java":
        full_command = _get_full_command(pid)
        if full_command and "GradleDaemon" in full_command:
            return "gradle"
    return name


def _get_parent_pid(pid: int) -> Optional[int]:
    """Return the parent PID of ``pid``.

    Returns None for PID 1 (init, the end of the chain), and on any subprocess
    failure or non-integer output.
    """
    if pid == 1:
        return None
    try:
        result = subprocess.run(
            ["ps", "-p", str(pid), "-o", "ppid="],
            capture_output=True,
            text=True,
            timeout=_SUBPROCESS_TIMEOUT,
        )
    except subprocess.TimeoutExpired:
        return None
    if result.returncode != 0:
        return None
    try:
        return int(result.stdout.strip())
    except ValueError:
        return None


def _get_ancestor_chain(max_depth: int = 4) -> List[str]:
    """Walk the process tree upward from the current process's parent.

    Returns a list of process names, stopping when a name or parent PID can no
    longer be resolved, or once ``max_depth`` entries have been collected.
    """
    chain: List[str] = []
    pid = os.getppid()
    while len(chain) < max_depth:
        name = _get_process_name(pid)
        if name is None:
            break
        chain.append(name)

        parent_pid = _get_parent_pid(pid)
        if parent_pid is None:
            break
        pid = parent_pid
    return chain


